/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');
const loadInter = makeLoadFont('Inter');

const { fontFamily: robotoMonoFamily } = loadRobotoMono();
const { fontFamily: interFamily } = loadInter();



export type NasdaqChartProps = Record<string, any>;

// Data defining the market structure
// Y-values are relative (0-100) representing price
const CANDLE_DATA = [
  { o: 60, h: 65, l: 45, c: 50 }, // 0: Bearish
  { o: 50, h: 55, l: 30, c: 35 }, // 1: Bearish
  { o: 35, h: 40, l: 15, c: 20 }, // 2: Bearish (The Order Block)
  { o: 20, h: 70, l: 18, c: 65 }, // 3: Bullish (Displacement, creates FVG)
  { o: 65, h: 85, l: 60, c: 80 }, // 4: Bullish (FVG locked in)
  { o: 80, h: 90, l: 75, c: 85 }, // 5: Bullish
  { o: 85, h: 88, l: 70, c: 75 }, // 6: Bearish (Retracement starts)
  { o: 75, h: 78, l: 42, c: 50 }, // 7: Bearish (Dips into FVG, touches 42)
  { o: 50, h: 80, l: 48, c: 75 }, // 8: Bullish (Bounces off FVG/OB)
  { o: 75, h: 100, l: 70, c: 95 }, // 9: Bullish (Continuation)
];

const NasdaqChart: React.FC<NasdaqChartProps> = ({
  backgroundColor = "#020617",
  transparentBackground = false,
  durationInSeconds = 8,
  chartTitle = "NASDAQ: NQ1! | 15m | Malloy Studio",
  bullishColor = "#00E5FF", // Cyan
  bearishColor = "#020617", // Match background
  bearishStrokeColor = "#0088FF", // Deep blue
  obFillColor = "rgba(0, 136, 255, 0.15)",
  obStrokeColor = "#0088FF",
  fvgFillColor = "rgba(0, 229, 255, 0.15)",
  fvgStrokeColor = "#00E5FF",
  gridColor = "#1E293B",
  textColor = "#94A3B8",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout metrics
  const paddingX = width * 0.08;
  const paddingY = height * 0.15;
  const chartW = width - paddingX * 2;
  const chartH = height - paddingY * 2;

  // Space for 12 candles to leave room on the right for the zones
  const numCandleSlots = 12;
  const candleW = chartW / numCandleSlots;
  const candleGap = candleW * 0.3;
  const actualCandleW = candleW - candleGap;

  // Coordinate mappers
  const getX = (index: number) => paddingX + index * candleW + candleW / 2;
  const getY = (val: number) => paddingY + chartH - (val / 100) * chartH;

  // Animation Timings
  const GRID_FADE_FRAME = 0;
  const OB_DRAW_FRAME = 65;
  const FVG_DRAW_FRAME = 85;

  // Opacities
  const gridOpacity = interpolate(frame, [GRID_FADE_FRAME, GRID_FADE_FRAME + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Zone Dimensions (OB = Candle 2 High/Low, FVG = Candle 2 High to Candle 4 Low)
  const OB_START_X = getX(2) - actualCandleW / 2;
  const OB_TOP_Y = getY(40);
  const OB_BOTTOM_Y = getY(15);
  const OB_H = OB_BOTTOM_Y - OB_TOP_Y;

  const FVG_START_X = getX(3) - actualCandleW / 2;
  const FVG_TOP_Y = getY(60); // Candle 4 low
  const FVG_BOTTOM_Y = getY(40); // Candle 2 high
  const FVG_H = FVG_BOTTOM_Y - FVG_TOP_Y;

  const MAX_ZONE_W = paddingX + chartW - OB_START_X;

  // Zone Animations
  const obWidthProgress = spring({
    frame: frame - OB_DRAW_FRAME,
    fps,
    config: { damping: 20, stiffness: 80, overshootClamping: true },
  });
  const obWidth = obWidthProgress * MAX_ZONE_W;

  const fvgWidthProgress = spring({
    frame: frame - FVG_DRAW_FRAME,
    fps,
    config: { damping: 20, stiffness: 80, overshootClamping: true },
  });
  const fvgWidth = fvgWidthProgress * (paddingX + chartW - FVG_START_X);

  const obLabelOpacity = interpolate(frame, [OB_DRAW_FRAME + 10, OB_DRAW_FRAME + 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const fvgLabelOpacity = interpolate(frame, [FVG_DRAW_FRAME + 10, FVG_DRAW_FRAME + 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Title & Metadata */}
      <div
        style={{
          position: "absolute",
          top: height * 0.05,
          left: paddingX,
          color: textColor,
          fontSize: 24,
          fontWeight: 600,
          opacity: gridOpacity,
          letterSpacing: "0.05em",
        }}
      >
        {chartTitle}
      </div>

      <svg
        width="100%"
        height="100%"
        style={{ position: "absolute", top: 0, left: 0, transition: "none" }}
      >
        {/* Y-Axis Grid & Labels */}
        {[0, 20, 40, 60, 80, 100].map((val) => {
          const y = getY(val);
          const priceStr = (15000 + val * 2.5).toFixed(1);
          return (
            <g key={`grid-y-${val}`} style={{ opacity: gridOpacity }}>
              <line
                x1={paddingX}
                y1={y}
                x2={width - paddingX}
                y2={y}
                stroke={gridColor}
                strokeWidth={1}
                strokeDasharray="4 4"
              />
              <text
                x={width - paddingX + 16}
                y={y + 6}
                fill={textColor}
                fontSize={16}
                fontFamily={robotoMonoFamily}
              >
                {priceStr}
              </text>
            </g>
          );
        })}

        {/* X-Axis Grid */}
        {[0, 2, 4, 6, 8, 10].map((val) => {
          const x = getX(val);
          return (
            <g key={`grid-x-${val}`} style={{ opacity: gridOpacity }}>
              <line
                x1={x}
                y1={paddingY}
                x2={x}
                y2={height - paddingY}
                stroke={gridColor}
                strokeWidth={1}
                strokeDasharray="4 4"
              />
            </g>
          );
        })}

        {/* Zones (Drawn behind candles) */}
        {/* Order Block Zone */}
        {obWidth > 0 && (
          <g>
            <rect
              x={OB_START_X}
              y={OB_TOP_Y}
              width={obWidth}
              height={OB_H}
              fill={obFillColor}
            />
            {/* Top and Bottom OB bounds */}
            <line
              x1={OB_START_X}
              y1={OB_TOP_Y}
              x2={OB_START_X + obWidth}
              y2={OB_TOP_Y}
              stroke={obStrokeColor}
              strokeWidth={2}
            />
            <line
              x1={OB_START_X}
              y1={OB_BOTTOM_Y}
              x2={OB_START_X + obWidth}
              y2={OB_BOTTOM_Y}
              stroke={obStrokeColor}
              strokeWidth={2}
            />
          </g>
        )}

        {/* Fair Value Gap Zone */}
        {fvgWidth > 0 && (
          <g>
            <rect
              x={FVG_START_X}
              y={FVG_TOP_Y}
              width={fvgWidth}
              height={FVG_H}
              fill={fvgFillColor}
            />
            {/* Top and Bottom FVG bounds */}
            <line
              x1={FVG_START_X}
              y1={FVG_TOP_Y}
              x2={FVG_START_X + fvgWidth}
              y2={FVG_TOP_Y}
              stroke={fvgStrokeColor}
              strokeWidth={2}
              strokeDasharray="6 4"
            />
            <line
              x1={FVG_START_X}
              y1={FVG_BOTTOM_Y}
              x2={FVG_START_X + fvgWidth}
              y2={FVG_BOTTOM_Y}
              stroke={fvgStrokeColor}
              strokeWidth={2}
              strokeDasharray="6 4"
            />
          </g>
        )}

        {/* Candlesticks */}
        {CANDLE_DATA.map((cData, i) => {
          // Candles 0-4 appear early. Candles 5-9 appear later to show the retest.
          const isEarly = i < 5;
          const delay = isEarly ? 15 + i * 8 : 110 + (i - 5) * 12;

          const progress = spring({
            frame: frame - delay,
            fps,
            config: { damping: 16, stiffness: 100, overshootClamping: true },
          });

          if (progress === 0) return null;

          // Interpolate price growing from Open
          const curC = cData.o + (cData.c - cData.o) * progress;
          const curH = cData.o + (cData.h - cData.o) * progress;
          const curL = cData.o + (cData.l - cData.o) * progress;

          const isBullish = curC >= cData.o;
          const fill = isBullish ? bullishColor : bearishColor;
          const stroke = isBullish ? bullishColor : bearishStrokeColor;

          const bodyTopY = getY(Math.max(cData.o, curC));
          const bodyBottomY = getY(Math.min(cData.o, curC));
          const bodyHeight = Math.max(bodyBottomY - bodyTopY, 2);

          const wickTopY = getY(curH);
          const wickBottomY = getY(curL);
          const x = getX(i);

          const candleOpacity = interpolate(progress, [0, 0.2], [0, 1], {
            extrapolateRight: "clamp",
          });

          return (
            <g key={`candle-${i}`} style={{ opacity: candleOpacity }}>
              {/* Wick */}
              <line
                x1={x}
                y1={wickTopY}
                x2={x}
                y2={wickBottomY}
                stroke={stroke}
                strokeWidth={2}
              />
              {/* Body */}
              <rect
                x={x - actualCandleW / 2}
                y={bodyTopY}
                width={actualCandleW}
                height={bodyHeight}
                fill={fill}
                stroke={stroke}
                strokeWidth={2}
                rx={2}
                ry={2}
              />
            </g>
          );
        })}
      </svg>

      {/* HTML Overlay for Labels (cleaner typography control) */}
      <div
        style={{
          position: "absolute",
          left: OB_START_X + 20,
          top: OB_TOP_Y + OB_H / 2 - 16,
          opacity: obLabelOpacity,
          color: obStrokeColor,
          fontFamily: robotoMonoFamily,
          fontSize: 18,
          fontWeight: "bold",
          backgroundColor: "rgba(2, 6, 23, 0.7)",
          padding: "4px 12px",
          borderRadius: 4,
          border: `1px solid ${obStrokeColor}`,
          display: "flex",
          alignItems: "center",
          transform: `translateY(${interpolate(obLabelOpacity, [0, 1], [10, 0])}px)`,
        }}
      >
        Bullish Order Block (+OB)
      </div>

      <div
        style={{
          position: "absolute",
          left: FVG_START_X + 20,
          top: FVG_TOP_Y + FVG_H / 2 - 16,
          opacity: fvgLabelOpacity,
          color: fvgStrokeColor,
          fontFamily: robotoMonoFamily,
          fontSize: 18,
          fontWeight: "bold",
          backgroundColor: "rgba(2, 6, 23, 0.7)",
          padding: "4px 12px",
          borderRadius: 4,
          border: `1px solid ${fvgStrokeColor}`,
          display: "flex",
          alignItems: "center",
          transform: `translateY(${interpolate(fvgLabelOpacity, [0, 1], [10, 0])}px)`,
        }}
      >
        Fair Value Gap (FVG)
      </div>
    </AbsoluteFill>
  );
};

export default NasdaqChart;